def greedy_pack(token_seqs, context_len):
    bins, current_bin, current_len = [], [], 0
    for seq in token_seqs:
        if current_len + len(seq) <= context_len:
            current_bin.append(seq)
            current_len += len(seq)
        else:
            if current_bin:
                bins.append(current_bin)
            current_bin = [seq]
            current_len = len(seq)
    if current_bin:
        bins.append(current_bin)
    return bins

import numpy as np

def build_causal_mask(seq_len: int, doc_spans):
    mask = np.zeros((seq_len, seq_len), dtype=bool)
    for start, end in doc_spans:
        for i in range(start, end):
            mask[i, start:i+1] = True
    return mask

def build_loss_mask(seq_len: int, loss_spans, pad_positions=None):
    lm = np.ones(seq_len, dtype=np.float32)
    if pad_positions:
        for pos in pad_positions:
            lm[pos] = 0.0
    for start, end in (loss_spans or []):
        lm[start:end] = 0.0
    return lm

class MinHashLSH:
    def __init__(self, num_perm=128, threshold=0.8):
        self.num_perm = num_perm
        self.threshold = threshold
        import hashlib, random
        r = random.Random(42)
        self.hash_fns = [(r.randint(1, 2**31), r.randint(0, 2**31))
                          for _ in range(num_perm)]

    def minhash(self, shingles):
        sig = []
        for a, b in self.hash_fns:
            mn = min((a * s + b) % (2**31) for s in shingles)
            sig.append(mn)
        return sig

    def jaccard(self, sig1, sig2):
        matches = sum(1 for a, b in zip(sig1, sig2) if a == b)
        return matches / len(sig1)
